class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.calls = {}

    def allow(self, key, now):
        window = [t for t in self.calls.get(key, []) if now - t < self.period]
        if len(window) >= self.max_calls:
            self.calls[key] = window
            return False
        window.append(now)
        self.calls[key] = window
        return True

