    SENSITIVE_KEYS = {"password", "token", "api_key", "ssn", "secret"}

    def _process(item):
        try:
            if isinstance(item, dict):
                new_dict = {}
                for k, v in item.items():
                    if isinstance(k, str) and k.lower() in SENSITIVE_KEYS:
                        new_dict[k] = '***'
                    else:
                        new_dict[k] = _process(v)
                return new_dict
            elif isinstance(item, (list, tuple)):
                res = [_process(i) for i in item]
                return type(item)(res)
            else:
                return item
        except Exception as e:
            print(f"DEBUG: processing error {e}")
            return item

    if not isinstance(record, (dict, list, tuple)):
        return record

    result = _process(record)

    if result is None and record is not None:
        return record

    return result

