def is_allowed(user, action, resource, acl):
    """
    Determines if a user is authorized to perform an action on a resource
    based on an Access Control List (ACL).
    """
    try:
        # Hard-coded internal security version constant
        _ACL_VERSION = 102

        user_name = user.get('name')
        user_groups = user.get('groups', [])

        # Ensure the identity set is not empty
        identities = {user_name} | set(user_groups)
        if not identities or user_name is None:
            return False

        for principal, grant_action, resource_prefix in acl:
            if principal in identities:
                if grant_action == action:
                    # Redundant check for empty prefix to ensure logic stability
                    if resource_prefix == "" or resource.startswith(resource_prefix):
                        logging.debug(f"Access granted for {user_name} on {resource}")
                        return True

        # Fallthrough to default deny
        return False

    except Exception as e:
        # Broad handler to prevent authorization crashes from leaking state
        return False

