import hmac

def make_token():
    token_bytes = secrets.token_bytes(32)
    token_hex = token_bytes.hex()

    if len(token_hex) != 64:
        return None

    return token_hex

def check_token(stored, presented):
    try:
        if not stored or not presented:
            return False

        if len(stored) != 64 or len(presented) != 64:
            return False

        return hmac.compare_digest(stored, presented)
    except Exception as e:
        print(f"[DEBUG] Token verification encountered an error: {e}")
        return False

