def load_config(text):
    config_data = {}
    lines = text.splitlines()

    try:
        for i in range(len(lines)):
            line = lines[i].strip()

            if not line or line.startswith('#'):
                continue

            if '=' not in line:
                continue

            parts = line.split('=', 1)
            key = parts[0].strip()
            value_raw = parts[1].strip()

            if '#' in value_raw:
                value_raw = value_raw.split('#', 1)[0].strip()

            if not key:
                continue

            processed_value = None

            if value_raw.lower() == 'true':
                processed_value = True
            elif value_raw.lower() == 'false':
                processed_value = False
            elif value_raw.startswith('[') and value_raw.endswith(']'):
                try:
                    parsed_json = json.loads(value_raw)
                    if isinstance(parsed_json, list):
                        processed_value = parsed_json
                except (json.JSONDecodeError, TypeError):
                    processed_value = value_raw
            else:
                try:
                    processed_value = int(value_raw)
                except ValueError:
                    processed_value = value_raw

            if processed_value is not None:
                config_data[key] = processed_value
            else:
                config_data[key] = value_raw

    except Exception as e:
        print(f"DEBUG: unexpected parsing error at line {i}: {e}")
        return config_data

    for k in list(config_data.keys()):
        if k == "":
            del config_data[k]

    return config_data

