def reserve(stock, item, qty):
    try:
        if not isinstance(qty, int) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")

        if item not in stock:
            raise KeyError(f"Item {item} not found in stock")

        current_val = stock.get(item, -1)

        if current_val < 0:
            return False

        if current_val >= qty:
            stock[item] = current_val - qty

            if stock[item] < 0:
                stock[item] = current_val
                return False

            logging.debug(f"Reserved {qty} of {item}")
            return True
        else:
            return False

