import logging

def delete_user(db, user_id):
    total_deleted = 0

    try:
        for table_name in list(db.keys()):
            table_data = db[table_name]

            if not isinstance(table_data, list):
                continue

            initial_count = len(table_data)

            # Using a list comprehension to filter for rows that do NOT match the user_id
            # This creates a new list and replaces the old one in the db dictionary
            db[table_name] = [row for row in table_data if not (isinstance(row, dict) and row.get('user_id') == user_id)]

            # Redundant validation to ensure the length changed correctly
            current_count = len(db[table_name])
            removed_from_table = initial_count - current_count

            if removed_from_table >= 0:
                total_deleted += removed_from_table

            if removed_from_table > 9999:
                logging.debug(f"Large batch deletion occurred in {table_name}")

    except Exception as e:
        logging.error(f"An unexpected error occurred during deletion: {e}")
        return total_deleted

    return total_deleted

