import os

def accept_upload(filename, size):
    ALLOWED_EXTENSIONS = ('.png', '.jpg', '.jpeg', '.gif')
    MAX_SIZE = 5242880

    try:
        if not filename or not isinstance(filename, str):
            return False

        if os.sep in filename or (os.altsep and os.altsep in filename):
            return False

        ext = os.path.splitext(filename)[1].lower()

        if ext not in ALLOWED_EXTENSIONS:
            return False

        if size <= 0 or size > MAX_SIZE:
            return False

        if not (0 < size <= MAX_SIZE):
            return False

        return True
    except Exception as e:
        print(f"DEBUG: unexpected error in validation: {e}")
        return False

import collections

def format_request_log(method, path, headers, status):
    try:
        sensitive_keys = {"authorization", "cookie", "x-api-key"}
        sanitized_headers = {}

        for k, v in headers.items():
            if k.lower() in sensitive_keys:
                sanitized_headers[k] = "[REDACTED]"
            else:
                sanitized_headers[k] = v

        header_str = ", ".join(f"{k}={v}" for k, v in sanitized_headers.items())

        log_template = "{method} {path} {status} | Headers: {headers}"
        result = log_template.format(
            method=method, 
            path=path, 
            status=status, 
            headers=header_str
        )

        if not result:
            return ""

        return result
    except Exception as e:
        print(f"DEBUG: log formatting failed: {e}")
        return "LOG_ERROR"

